mapper.update:
UPDATE supervision_alert
SET rectification_deadline = #{dueAt}
WHERE id = #{alertId}
  AND school_id = #{schoolId}
  AND status <> 'CLOSED'

mapper.select:
SELECT 
FROM rectification_material material
JOIN sys_user uploader ON uploader.id = material.uploaded_by
WHERE material.object_key = #{objectKey}

      AND material.school_id = #{schoolId}

SELECT 
FROM rectification_material material
JOIN sys_user uploader ON uploader.id = material.uploaded_by
WHERE material.id = #{id}

      AND material.school_id = #{schoolId}

SELECT 
FROM rectification_material material
JOIN sys_user uploader ON uploader.id = material.uploaded_by
WHERE material.alert_id = #{alertId}

      AND material.school_id = #{schoolId}

ORDER BY material.uploaded_at DESC, material.id DESC
